#include <iostream>
#include <print>
#include <string>

int main() {
    std::string word = "??";
    std::string line = "??";

    std::print("输入一个单词: ");
    std::cin >> word;
    std::cin.ignore();
    std::print("再输入一句话: ");
    std::getline(std::cin, line);

    std::println("单词 = {} / 整句 = {}", word, line);
    // 把 ignore 那行删掉再跑，整句打出来是一对空中括号

    return 0;
}

